    public void getClaimsSearch(BigDecimal claimTypeIdParam,String claimFolderParam,String caseNumber,String claimYearParam,String policeIdParam,String repeatedFlagParam , BigDecimal degId , BigDecimal criminalType)
    {
        ADFContext.getCurrent().getSessionScope().put("pClaimDeleted", "N");
        ViewCriteria criteria = this.getViewCriteria("ExcClaimsVOCriteriaSearchScreen");
        String claimEntity = ADFContext.getCurrent().getSessionScope().get("ClaimEntity")+"" ;
        String ClaimKplayaFlag = ADFContext.getCurrent().getSessionScope().get("ClaimKplayaFlag")+"" ;
        System.err.println( ADFContext.getCurrent().getSessionScope().get("ClaimEntity")+" claimTypeIdParam ==>"+ claimTypeIdParam+" claimFolderParam ==>"+ claimFolderParam+" caseNumber ==>"+ caseNumber+" claimYearParam ==>"+ claimYearParam+" policeIdParam ==>"+ policeIdParam+" repeatedFlagParam ==>"+ repeatedFlagParam);
        this.applyViewCriteria(criteria);
        this.setclaimTypeIdParam(claimTypeIdParam);
        this.setclaimFolderParam(claimFolderParam);
        this.setbindCaseNumber(caseNumber);
        this.setclaimYearParam(claimYearParam);
        if (claimEntity.compareToIgnoreCase("0")==0){
        this.setpoliceIdParam(policeIdParam);
            System.err.println("policeIdParam  ***  policeIdParam");
        }
        else
        {
            
            this.setpoliceIdParam(claimEntity);
            if (ClaimKplayaFlag.compareToIgnoreCase("T")==0){
            this.setpoliceIdParam(policeIdParam);  
            System.out.println("policeIdParam  ***  policeIdParam");
            }
            
        }
        this.setBCDegreeParam(degId);
        this.setcriminalTypeParam(criminalType);
        this.setrepeatedFlagParam(repeatedFlagParam);
        this.executeQuery();
//        System.err.println(" claimTypeIdParam ==>"+this.getQuery());
    }

